  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When you cut a standard roll to fulfill an order, must each order's full length be cut as one continuous piece from a single standard roll, or can an order's length be assembled by splicing together multiple cut pieces?"
  ],
  "rationale": "The response asks for a single policy choice regarding whether orders must be cut as continuous pieces or can be spliced, which constitutes one semantically independent question."
}

